import boto3
from typing import Dict, Any, List

def extract_and_normalize_expense(document_bytes: bytes) -> Dict[str, Any]:
    client = boto3.client('textract')
    response = client.analyze_expense(
        Document={'Bytes': document_bytes}
    )
    expense_doc = response['ExpenseDocuments'][0]
    summary_fields = expense_doc.get('SummaryFields', [])
    line_item_groups = expense_doc.get('LineItemGroups', [])

    def get_field_value(fields: List[Dict[str, Any]], type_name: str) -> str:
        for field in fields:
            if field['Type']['Text'] == type_name:
                return field['ValueDetection']['Text']
        return ''

    normalized = {
        'vendor_name': get_field_value(summary_fields, 'VENDOR_NAME'),
        'invoice_date': get_field_value(summary_fields, 'INVOICE_RECEIVED_DATE'),
        'due_date': get_field_value(summary_fields, 'DUE_DATE'),
        'total_amount': get_field_value(summary_fields, 'TOTAL'),
        'currency': 'USD',
        'line_items': []
    }

    for group in line_item_groups:
        for line_item in group.get('LineItems', []):
            fields = line_item.get('LineItemExpenseFields', [])
            line = {
                'description': get_field_value(fields, 'DESCRIPTION'),
                'item': get_field_value(fields, 'ITEM'),
                'quantity': get_field_value(fields, 'QUANTITY'),
                'unit_price': get_field_value(fields, 'UNIT_PRICE'),
                'total_price': get_field_value(fields, 'TOTAL_PRICE')
            }
            # Filter out empty lines
            if any(line.values()):
                normalized['line_items'].append(line)

    return normalized
